		public new IceBoss parent;

		public IceBossIntroState(string newName, FSM newFSM, IceBoss newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			Vector3 position = parent.transform.position;
			Vector3[] array = new Vector3[4]
			{
				position,
				position + new Vector3(-0.5f, 0.5f, 0f),
				position + new Vector3(0.5f, 0.5f, 0f),
				position + new Vector3(0f, 1f, 0f)
			};
			for (int i = 0; i < array.Length; i++)
			{
				PoolManager.GetPoolItem<ParticleEffect>("IceFloorBurst").Emit(30, array[i], null, null, 0.8f);
			}
			parent.anim.Play("Intro", -1, 0f);
			parent.iceWheelAnim.Play("Fold", -1, 0f);
			delayStopwatchID = ChaosStopwatch.Begin(1.5f);
			laughPlayed = false;
			introFinished = false;
		}

		public override void Update()
		{
			if (!Level.isBossRushMode && !introFinished && ChaosStopwatch.Check(delayStopwatchID))
			{
				if (!laughPlayed)
				{
					laughPlayed = true;
					SoundManager.PlayAudio("IceBossLaugh");
					delayStopwatchID = ChaosStopwatch.Begin(1.83f);
					parent.anim.Play("Laugh", -1, 0f);
					parent.iceWheelAnim.Play("Open", -1, 0f);
				}
				else if (!introFinished)
				{
					introFinished = true;
					parent.anim.Play("Idle", -1, 0f);
					parent.iceWheelAnim.Play("Idle", -1, 0f);
				}
			}
		}
	}

	public class IceBossOutroState(string newName, FSM newFSM, IceBoss newEnt) : State<IceBoss>(newName, newFSM, newEnt)
	{
		private bool firstFrame;

		private bool fortified;

		private bool outroFinished;

		private float fortifyPause = 0.35f;

		private int fortifyPauseTimerID;

		public override void OnEnter()
		{
			parent.anim.Play("Fortify", -1, 0f);
			parent.iceWheelAnim.Play("Hide", -1, 0f);
			firstFrame = true;
			fortified = false;
			outroFinished = false;
		}

		public override void Update()
		{
			if (firstFrame)
			{
				firstFrame = false;
			}
			else if (!fortified)
			{
				if (parent.anim.AnimPlayed())
				{
					fortified = true;
					fortifyPauseTimerID = ChaosStopwatch.Begin(fortifyPause);
------
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.iceWheelCenterSprite.sortingLayerName = "Actor";
			parent.iceWheelAnim.Play("SnowFlakeForm", -1, 0f);
			shatterEffectPlayed = false;
			SoundManager.PlayAudioWithDistance("StandardSpin", parent.transform.position);
			string audioID = "IceForm";
			Vector2? soundOrigin = parent.transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		}

		public override void Update()
		{
			base.Update();
			if (!shatterEffectPlayed && parent.iceWheelAnim.AnimPlayed(0.9f))
			{
				ShatterSnowFlake();
				shatterEffectPlayed = true;
			}
			else if (parent.iceWheelAnim.AnimPlayed(0.66f))
			{
				parent.iceWheelCenterSprite.sortingLayerName = "OverlayDoodad";
			}
		}

		public void ShatterSnowFlake()
		{
			Vector3 vector = new Vector3(0f, 3.25f, 0f);
			PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(40, parent.iceWheelTrans.position + vector + Vector3.up);
			PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(40, parent.iceWheelTrans.position + vector + Vector3.down);
			PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(40, parent.iceWheelTrans.position + vector + Vector3.left);
			PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(40, parent.iceWheelTrans.position + vector + Vector3.right);
			string audioID = "IceSolidify";
			Vector2? soundOrigin = parent.transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		}
	}

