		private float moveSpeed;

		private List<WaterBarrage> wbList = new List<WaterBarrage>();

		private WaterBarrage currentWB;

		private int attackLevel;

		private bool spinStarted;

		private bool finalSpinStarted;

		private int ultSpawnCount = 12;

		private int ultSpawnSeed;

		private Vector2 ultVector;

		private IceShard currentIS;

		public new IceBoss parent;

		public IceBossWaterBarrageState(string newName, FSM newFSM, IceBoss newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
			parent.CreateBossPool<WaterBarrage>(WaterBarrage.Prefab, 35);
			parent.CreateBossPool<IceShard>(IceShard.ArrowPrefab, 50);
			SetBossPoolVars();
		}

		private void SetBossPoolVars()
		{
			GenericPool<WaterBarrage> bossPool = parent.GetBossPool<WaterBarrage>(typeof(WaterBarrage));
			int itemCount = bossPool.ItemCount;
			for (int i = 0; i < itemCount; i++)
			{
				currentWB = bossPool.GetItem();
				currentWB.destroyOnDisable = false;
				currentWB.ResetProjectile();
			}
			GenericPool<IceShard> bossPool2 = parent.GetBossPool<IceShard>(typeof(IceShard));
			itemCount = bossPool2.ItemCount;
			for (int j = 0; j < itemCount; j++)
			{
				currentIS = bossPool2.GetItem();
				currentIS.moveSpeed = 25f;
				currentIS.flyTime = 0.15f;
				currentIS.destroyOnDisable = false;
				currentIS.ignoreProjectileCollisions = true;
				currentIS.ResetProjectile();
			}
		}

		public override void OnEnter()
		{
			base.OnEnter();
			spinStarted = false;
			finalSpinStarted = false;
			parent.anim.Play("BackhandDown", -1, 0f);
			if (isUltimate)
			{
				attackLevel = 2;
				windupTime = StdWindupTime * 3f;
				exitTime = StdExitTime * 1f;
				spawnCount = (int)Mathf.Lerp(20f, 24f, currentDiffValue);
				moveSpeed = Mathf.Lerp(24f, 32f, currentDiffValue);
			}
			else
			{
				attackLevel = 1;
				windupTime = StdWindupTime * 1.5f;
				exitTime = StdExitTime;
				spawnCount = (int)Mathf.Lerp(7f, 9f, currentDiffValue);
				moveSpeed = Mathf.Lerp(20f, 28f, currentDiffValue);
			}
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
			releaseInterval = StdWindupTime * 0.25f;
			releaseStopwatchID = ChaosStopwatch.Begin(windupTime, useInterval: true, releaseInterval, spawnCount);
			CreateWaterBarrageRing();
		}

		public override void WindupUpdate()
		{
			parent.anim.Play("BackhandDown", -1, 0f);
		}

		public override void ExecuteSkill()
		{
			if (!spinStarted)
			{
				parent.anim.Play("Spin", -1, 0f);
				spinStarted = true;
			}
			switch (ChaosStopwatch.CheckInterval(releaseStopwatchID))
			{
			case StopwatchState.Running:
				if (spinStarted && parent.anim.AnimPlayed())
				{
					parent.anim.Play("Spin", -1, 0f);
				}
				break;
			case StopwatchState.Ready:
				if (wbList.Count > 0 && wbList[0] != null && parent.closestTargetInfo != null && parent.closestTargetInfo.hurtBoxTransform != null)
				{
					wbList[0].Release(parent.closestTargetInfo.hurtBoxTransform.position);
					wbList.RemoveAt(0);
					SoundManager.PlayAudioWithDistance((!isUltimate) ? "WaterArcBasic" : "IceSwordSwing", parent.transform.position);
				}
				break;
			case StopwatchState.Done:
				if (!finalSpinStarted)
				{
					if (parent.anim.AnimPlayed())
					{
						finalSpinStarted = true;
						parent.anim.Play("SpinFancy", -1, 0f);
					}
				}
				else if (parent.anim.AnimPlayed())
				{
					base.ExecuteSkill();
				}
				break;
			}
		}

		private void CreateWaterBarrageRing()
		{
			wbList.Clear();
			spawnTransform = parent.attackOriginTrans;
			spawnPosition = spawnTransform.position;
			int randomOffset = UnityEngine.Random.Range(0, spawnCount);
			if (!parent.isFacingRight)
			{
				for (int i = 0; i < spawnCount; i++)
				{
					CreateWaterBarrage(i, randomOffset);
				}
				return;
			}
			for (int num = spawnCount - 1; num >= 0; num--)
			{
				CreateWaterBarrage(num, randomOffset);
			}
		}

		private void CreateWaterBarrage(int spawnIndex, int randomOffset)
		{
			spawnOffset = Globals.GetCirclePositionVector(spawnCount, spawnIndex + randomOffset);
			currentWB = parent.GetBossPoolItem<WaterBarrage>();
			if (!(currentWB == null) && !(currentWB.transform == null))
			{
				currentWB.transform.position = spawnPosition + spawnOffset;
				currentWB.clockwise = parent.isFacingRight;
				currentWB.isUltimate = isUltimate;
				currentWB.attackBox.SetAttackInfo(parent.skillCategory, skillID, attackLevel, isUltimate);
				currentWB.followTrans = spawnTransform;
				currentWB.windupTime = windupTime;
				currentWB.moveSpeed = moveSpeed;
				currentWB.RecycleProjectile();
				WaterBarrage waterBarrage = currentWB;
				waterBarrage.ultResetEventHandlers = (WaterBarrage.UltResetEventHandlers)Delegate.Remove(waterBarrage.ultResetEventHandlers, new WaterBarrage.UltResetEventHandlers(CreateUltBurst));
				if (isUltimate)
				{
					WaterBarrage waterBarrage2 = currentWB;
					waterBarrage2.ultResetEventHandlers = (WaterBarrage.UltResetEventHandlers)Delegate.Combine(waterBarrage2.ultResetEventHandlers, new WaterBarrage.UltResetEventHandlers(CreateUltBurst));
				}
				wbList.Add(currentWB);
			}
		}

		private void CreateUltBurst(Vector2 givenPosition)
		{
			ultSpawnSeed = UnityEngine.Random.Range(0, ultSpawnCount);
			for (int i = 0; i < ultSpawnCount; i++)
			{
				ultVector = Globals.GetCirclePositionVector(ultSpawnCount, ultSpawnSeed + i);
				currentIS = parent.GetBossPoolItem<IceShard>();
				if (currentIS == null || currentIS.transform == null)
				{
					break;
				}
				currentIS.transform.position = givenPosition;
				currentIS.attackBox.SetAttackInfo(parent.skillCategory, skillID, attackLevel, isUltimate);
				currentIS.attackBox.knockbackOverwriteVector = ultVector;
				currentIS.RecycleProjectile();
				currentIS.PointIceShard(ultVector);
				currentIS.ReleaseIceShard(ultVector);
			}
		}
	}

