public class IceBossIceLanceState : BossSkillState
{
	private int halfCount = 1;

	private float spawnRange;

	private Vector2 spawnPosition;

	private Transform spawnTransform;

	private Vector2 offsetVector;

	private List<IceLance> lanceList = new List<IceLance>();

	private IceLance currentIL;

	private float lanceSpeed;

	private int delayStopwatchID;

	private float delayTime;

	private bool delayStarted;

	private Vector3 lastTargetPos;

	private List<Vector2> vecList = new List<Vector2>();

	private float vecLerpValue;

	public new IceBoss parent;

	public IceBossIceLanceState(string newName, FSM newFSM, IceBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
	}

	public override void OnEnter()
	{
		base.OnEnter();
		windupTime = StdWindupTime;
		windupStopwatchID = ChaosStopwatch.Begin(windupTime * 1.25f);
		delayTime = windupTime * 0.35f;
		delayStarted = false;
		halfCount = (int)Mathf.Lerp(1f, 3f, currentDiffValue);
		spawnRange = Mathf.Lerp(2f, 3f, currentDiffValue);
		lanceSpeed = Mathf.Lerp(32f, 42f, currentDiffValue);
		offsetVector = new Vector2(Mathf.Lerp(1.25f, 0.75f, currentDiffValue), 0f);
		spawnPosition = Vector3.up * spawnRange;
		SpawnLances();
		parent.anim.PlayDirectional("RainbowCast" + parent.facingDirection);
	}

	public override void WindupUpdate()
	{
		RetargetLances();
	}

	public override void ExecuteSkill()
	{
		if (!delayStarted)
		{
			delayStarted = true;
			delayStopwatchID = ChaosStopwatch.Begin(delayTime);
			RetargetLances();
			{
				foreach (IceLance lance in lanceList)
				{
					if (lance != null)
					{
						lance.anim.Play("Flash", -1, 0f);
					}
				}
				return;
			}
		}
		if (!ChaosStopwatch.Check(delayStopwatchID))
		{
			return;
		}
		foreach (IceLance lance2 in lanceList)
		{
			if (!(lance2 == null))
			{
				lance2.moveSpeed = lanceSpeed;
				lance2.anim.Play("Idle", -1, 0f);
				lance2.transform.SetParent(parent.bossObjects);
			}
		}
		parent.FaceTarget(lastTargetPos, parent.animFacingDirections);
		parent.anim.PlayDirectional("TwoHandCast" + parent.facingDirection, -1, 0.5f);
		SoundManager.PlayAudioWithDistance("FrostArcherIceArrowShower", parent.transform.position);
		base.ExecuteSkill();
	}

	private void RetargetLances()
	{
		if (parent.closestTargetInfo.hurtBoxTransform == null)
		{
			return;
		}
		vecLerpValue = ChaosStopwatch.GetTimePercentage(windupStopwatchID) * 1.5f;
		lastTargetPos = parent.closestTargetInfo.hurtBoxTransform.position;
		targetVector = (lastTargetPos - spawnTransform.position).normalized;
		spawnTransform.localEulerAngles = Globals.GetRotationVector(targetVector);
		targetVector = Globals.GetPerpendicular(targetVector, horizontal: false) * 0.8f;
		for (int i = 0; i < halfCount * 2 + 1; i++)
		{
			currentIL = lanceList[i];
			if (!(currentIL == null))
			{
				currentIL.transform.localPosition = Vector2.Lerp(spawnPosition, vecList[i], vecLerpValue);
				currentIL.moveVector = (lastTargetPos + (Vector3)(targetVector * (i - halfCount)) - currentIL.transform.position).normalized;
				currentIL.isPointedAtMoveVector = false;
			}
		}
		parent.FaceTarget(parent.closestTargetInfo.hurtBoxTransform.position, parent.animFacingDirections);
		parent.anim.PlayDirectional("RainbowCast" + parent.facingDirection, -1, parent.anim.GetAnimTime());
	}

	private void SpawnLances()
	{
		vecList.Clear();
		lanceList.Clear();
		if (spawnTransform == null)
		{
			spawnTransform = new GameObject().transform;
			spawnTransform.SetParent(parent.bossObjects);
		}
		spawnTransform.position = parent.attackOriginTrans.position;
		spawnTransform.localEulerAngles = Vector3.zero;
		for (int i = -halfCount; i <= halfCount; i++)
		{
			lanceList.Add(CreateLance(spawnPosition));
			vecList.Add(i * offsetVector * spawnRange);
		}
		spawnTransform.localEulerAngles = Globals.GetRotationVector(targetVector);
		SoundManager.PlayAudioWithDistance("IceFormQuick", parent.transform.position);
		PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(50, (Vector2)parent.attackOriginTrans.position + targetVector * spawnRange);
	}

	private IceLance CreateLance(Vector2 givenLocation)
	{
		IceBoss parentEntity = parent;
		GameObject prefab = IceLance.Prefab;
		Vector3? givenPosition = parent.transform.position;
		Transform givenTrans = spawnTransform;
		currentIL = (IceLance)Projectile.CreateProjectile(parentEntity, prefab, givenPosition, null, givenTrans);
		currentIL.transform.localPosition = givenLocation;
		currentIL.attackBox.SetAttackInfo(parent.skillCategory, skillID);
		currentIL.moveSpeed = 0f;
		currentIL.anim.Play("Form", -1, 0f);
		currentIL.flyTime = 10f;
		return currentIL;
	}
}

public class IceBossWaterBombState : BossSkillState
{
	private int spawnCount = 3;

	private float spawnRange = 1f;

	private Vector2 spawnPosition;

	private float throwTime;

	private List<WaterBomb> wbList = new List<WaterBomb>();

	private WaterBomb currentWB;

	private float orbitRadius = 3f;

	private float orbitLerpValue;

	private int positionCount = 12;

	private int positionOffset = 4;

	private int positionSeed;

	public new IceBoss parent;

	public IceBossWaterBombState(string newName, FSM newFSM, IceBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
	}

	public override void OnEnter()
	{
		base.OnEnter();
		parent.anim.Play("CrossArmCast", -1, 0f);
		windupTime = StdWindupTime;
		exitTime = StdExitTime * 2f;
		throwTime = Mathf.Lerp(0.7f, 0.5f, currentDiffValue);
		windupStopwatchID = ChaosStopwatch.Begin(windupTime);
		CreateWaterBombs();
	}

	public override void WindupUpdate()
	{
		orbitLerpValue = Mathf.Lerp(spawnRange, orbitRadius, ChaosStopwatch.GetTimePercentage(windupStopwatchID));
		foreach (WaterBomb wb in wbList)
		{
			wb.movement.OrbitTarget(spawnPosition, useTransform: true);
			wb.movement.orbitRadius = orbitLerpValue;
		}
	}

	public override void ExecuteSkill()
	{
		ThrowWaterBombs();
		parent.anim.Play("DoubleCast", -1, 0.67f);
		SoundManager.PlayAudioWithDistance("WaterArcBasic", parent.transform.position);
		base.ExecuteSkill();
	}

	private void CreateWaterBombs()
	{
		wbList.Clear();
		spawnPosition = parent.transform.position;
		for (int i = 0; i < spawnCount; i++)
		{
			currentWB = ChaosInst<WaterBomb>(WaterBomb.Prefab);
			currentWB.initiateOnStart = false;
			currentWB.attack.SetAttackInfo(parent.skillCategory, skillID);
			currentWB.baseFlightTime = throwTime;
			currentWB.movement.InitOrbitAngle(Globals.GetCirclePositionVector(spawnCount, i));
			wbList.Add(currentWB);
		}
	}

	private void ThrowWaterBombs()
	{
		spawnPosition = ((parent.UpdateTargetInfo() != null) ? parent.closestTargetInfo.position : parent.transform.position);
		positionSeed = UnityEngine.Random.Range(0, positionOffset);
		for (int i = 0; i < spawnCount; i++)
		{
			if (!(wbList[i] == null))
			{
				currentWB = wbList[i];
				currentWB.targetPosition = spawnPosition + Globals.GetCirclePositionVector(positionCount, i * positionOffset + positionSeed) * orbitRadius;
				currentWB.InitThrow();
			}
		}
	}
}

