public class LightningBossTeleStrikeState : BossUltimateState
{
	private const int UltAtkCount = 50;

	private Vector2[] ultPathArr = new Vector2[50];

	private int ultSpawnCounter;

	private int ultDashCounter;

	private int warningCount = 2;

	private List<ShockBurstOrb> orbList = new List<ShockBurstOrb>();

	private ShockBurstOrb currentBO;

	private Vector2 prevOrbLocation;

	private Vector2 currOrbLocation;

	private int atkCount = 7;

	private float atkInterval = 0.35f;

	private float overShootValue = 3f;

	private int orbStopwatchID;

	private bool orbCompleted;

	private int dashStopwatchID;

	private bool dashCompleted;

	private bool ultAnimPlayed;

	private bool timersStarted;

	private bool batThrown;

	private bool dashToPosCompleted;

	public new LightningBoss parent;

	public LightningBossTeleStrikeState(string newName, FSM newFSM, LightningBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
	}

	public override void OnEnter()
	{
		if (!parent.DashToPosition(name, TeleStrikeGuyPos))
		{
			dashToPosCompleted = true;
			ultAnimPlayed = false;
			timersStarted = false;
			batThrown = false;
			base.OnEnter();
			parent.SetColliderStatus(givenStatus: true, partnerStatus: true);
			parent.Partner.MoveAndAnimate(TeleStrikeGirlPos, "Lookout");
			parent.Partner.dashStopwatch.SetDelay(0.05f);
			windupTime = StdWindupTime;
			windupStopwatchID = ChaosStopwatch.Begin(windupTime * 1.25f);
			exitTime = StdExitTime * 1.75f;
			warningCount = (int)Mathf.Lerp(2f, 0f, currentDiffValue);
			orbList.Clear();
			if (isUltimate)
			{
				ultSpawnCounter = 0;
				ultDashCounter = 0;
				atkCount = 50;
				atkInterval = 0.125f;
				DeterminePath();
				QueueWarning(0);
			}
			else
			{
				atkCount = 7;
				atkInterval = windupTime * 0.9f;
			}
			prevOrbLocation = parent.transform.position;
			orbCompleted = false;
			dashCompleted = false;
			if (isUltimate)
			{
				parent.anim.Play("HammerSummon", -1, 0f);
				Globals.ChaosInst<LightningStrike>(LightningStrike.Prefab, null, parent.transform.position);
				PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(2, parent.transform.position + Vector3.up * 2.5f + Globals.Vector3RightHalf);
				PoolManager.GetPoolItem<ParticleEffect>("LightningAuraEffect").Emit(2, parent.transform.position + Vector3.up * 2.5f + Globals.Vector3RightHalf);
			}
			else
			{
				parent.anim.Play("BatSpawn", -1, 0f);
			}
		}
	}

	private Vector2 GetOverShootPosition(Vector3 givenPosition)
	{
		return ((parent.UpdateTargetInfo() != null) ? (parent.closestTargetInfo.position + overShootValue * (parent.closestTargetInfo.position - givenPosition).normalized) : parent.transform.position) + (Vector3)UnityEngine.Random.insideUnitCircle * 0.5f;
	}

	public override void ExecuteSkill()
	{
		if (!timersStarted)
		{
			orbStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, atkInterval, atkCount);
			dashStopwatchID = ChaosStopwatch.Begin(0.5f, useInterval: true, atkInterval, atkCount);
			timersStarted = true;
		}
		if (!orbCompleted)
		{
			switch (ChaosStopwatch.CheckInterval(orbStopwatchID))
			{
			case StopwatchState.Ready:
				if (isUltimate)
				{
					if (!ultAnimPlayed)
					{
						ultAnimPlayed = true;
						parent.anim.Play("BatSpin", -1, 0f);
					}
					currOrbLocation = ultPathArr[ultSpawnCounter];
					QueueWarning(ultSpawnCounter + warningCount);
					switch (ultSpawnCounter % 5)
					{
					case 2:
						CreateLightningCorners(givenStatus: false);
						break;
					case 4:
						CreateLightningCorners(givenStatus: true);
						break;
					}
					ultSpawnCounter++;
					if (ultSpawnCounter % 2 == 0)
					{
						SoundManager.PlayAudioWithDistance("StandardHeavySwing", parent.transform.position, null, 24f, 0.35f);
						LightningBurst.CreateBurst(parent.transform.position + Vector3.up, parent.skillCategory, skillID, 3, 2f);
					}
				}
				else
				{
					currOrbLocation = GetOverShootPosition(prevOrbLocation);
					parent.FaceTarget(currOrbLocation);
					parent.anim.Play("BatSwing", -1, 0f);
				}
				CreateBurstOrb(currOrbLocation);
				prevOrbLocation = currOrbLocation;
				break;
			case StopwatchState.Done:
				orbCompleted = true;
				break;
			}
		}
		if (dashCompleted)
		{
			return;
		}
		switch (ChaosStopwatch.CheckInterval(dashStopwatchID))
		{
		case StopwatchState.Ready:
			if (orbList.Count > 0)
			{
				if (isUltimate)
				{
					currOrbLocation = ultPathArr[ultDashCounter];
					ultDashCounter++;
				}
				else
				{
					currOrbLocation = orbList[0].throwScript.targetPosition;
				}
				parent.Partner.currentBO = orbList[0];
				parent.Partner.QueueMode("Dash", currOrbLocation, 2, skillID, (!isUltimate) ? 1 : 2);
				orbList.RemoveAt(0);
			}
			break;
		case StopwatchState.Done:
			dashCompleted = true;
			base.ExecuteSkill();
			if (isUltimate)
			{
				parent.anim.Play("HammerEnd", -1, 0f);
				PoolManager.GetPoolItem<ParticleEffect>("LightningAuraEffect").Emit(3, parent.transform.position + Vector3.up * 2f + Globals.Vector3LeftHalf * parent.transform.localScale.x);
			}
			else
			{
				parent.anim.Play("BatThrow", -1, 0f);
			}
			break;
		}
	}

	public override void Update()
	{
		if (!isUltimate && !batThrown && dashCompleted && parent.anim.AnimPlayed(0.34f))
		{
			parent.bossBat.Throw(parent.transform.position, !parent.isFacingRight);
			batThrown = true;
		}
		base.Update();
	}

	public override void OnExit()
	{
		if (dashToPosCompleted)
		{
			dashToPosCompleted = false;
			base.OnExit();
			Vector2 vector = parent.transform.position + Vector3.right * 0.875f * parent.transform.localScale.x;
			PoolManager.GetPoolItem<ParticleEffect>("MetalDebrisEmitter").Emit(5, vector, ParticleEffectOverrides.StartSpeed1);
			PoolManager.GetPoolItem<ParticleEffect>("MetalSparkEmitter").Emit(6, vector);
			ChaosInst<LightningStrike>(LightningStrike.Prefab, vector);
			LightningBurst.CreateBurst(vector, string.Empty, string.Empty);
			SoundManager.PlayWithDistAndSPR("ShatterStone", vector);
		}
	}

	private void CreateBurstOrb(Vector2 givenPosition)
	{
		currentBO = parent.GetBossPoolItem<ShockBurstOrb>();
		currentBO.transform.position = parent.transform.position + Vector3.down;
		currentBO.Init(parent.skillCategory, skillID, (!isUltimate) ? 1 : 2, givenPosition);
		currentBO.useInitBurst = !isUltimate;
		orbList.Add(currentBO);
	}

	private void DeterminePath()
	{
		int num = ((!Globals.RandBool) ? 5 : 2);
		for (int i = 0; i < atkCount; i++)
		{
			int pingPong = GetPingPong(i + num, 3);
			int count = parent.gridArray[pingPong].Count;
			ref Vector2 reference = ref ultPathArr[i];
			reference = parent.gridArray[pingPong][UnityEngine.Random.Range(0, count)];
		}
	}

	private int GetPingPong(int givenValue, int givenMax)
	{
		if (givenMax <= 0)
		{
			return 0;
		}
		if ((int)((float)givenValue / (float)givenMax) % 2 == 0)
		{
			return givenValue % givenMax;
		}
		return givenMax - givenValue % givenMax;
	}

	private void QueueWarning(int givenIndex, int givenCount = 1)
	{
		if (givenIndex + givenCount < atkCount)
		{
			for (int i = givenIndex; i < givenIndex + givenCount; i++)
			{
				parent.CreateWarning(ultPathArr[i] + Vector2.up, ultPathArr[i + 1] + Vector2.up);
			}
		}
	}

	private void CreateLightningCorners(bool givenStatus)
	{
		if (givenStatus)
		{
			parent.CreateStream(skillID, parent.cornerList[0], parent.cornerList[1], 1, 0.1f, 1.5f);
			parent.CreateStream(skillID, parent.cornerList[1], parent.cornerList[3], 1, 0.1f, 1.5f);
			parent.CreateStream(skillID, parent.cornerList[3], parent.cornerList[2], 1, 0.1f, 1.5f);
			parent.CreateStream(skillID, parent.cornerList[2], parent.cornerList[0], 1, 0.1f, 1.5f);
		}
		else
		{
			parent.CreateWarning(parent.cornerList[0], parent.cornerList[1], 0.25f);
			parent.CreateWarning(parent.cornerList[1], parent.cornerList[3], 0.25f);
			parent.CreateWarning(parent.cornerList[3], parent.cornerList[2], 0.25f);
			parent.CreateWarning(parent.cornerList[2], parent.cornerList[0], 0.25f);
		}
	}
}

