		currentSB.Initialize(parent, skillID, (float)givenIndex * rangeSpread, 9 - givenIndex, windupTime * 0.5f, windupTime * 2f / ((float)givenIndex + 2f));
	}
}

public class LightningBossShockNetState : BossSkillState
{
	private ParticleSystemOverride lfOverride = new ParticleSystemOverride
	{
		radius = 5f
	};

	private Vector2 spawnPosition;

	private Vector2 targetPosition;

	private int orbCount = 5;

	private int randomSeed;

	private bool slamPlayed;

	private bool standPlayed;

	private bool crossArmPlayed;

	private bool landStarted;

	private bool landCompleted;

	private ChaosQuickStopwatch landStopwatch = new ChaosQuickStopwatch(0.25f);

	private List<MetalOrb> moList = new List<MetalOrb>();

	private MetalOrb currentMO;

	public new LightningBoss parent;

	public LightningBossShockNetState(string newName, FSM newFSM, LightningBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
	}

	public override void OnEnter()
	{
		base.OnEnter();
		slamPlayed = false;
		standPlayed = false;
		crossArmPlayed = false;
		windupTime = StdWindupTime * 0.75f;
		windupStopwatchID = ChaosStopwatch.Begin(windupTime);
		exitTime = StdExitTime * 3f;
		spawnPosition = parent.GetTrackingPosition();
		parent.SetColliderStatus(givenStatus: true, partnerStatus: false);
		parent.anim.Play("GroundSlam", -1, 0f);
		parent.Partner.PlayAnim("Takeoff");
		CameraController.ShakeCamera(0.25f);
		ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("LightningAuraEffect");
		poolItem.Emit(2, spawnPosition);
		poolItem.Emit(1, spawnPosition + Vector2.up, null, null, 0.1f);
		poolItem.Emit(1, spawnPosition + Vector2.up * 1.5f, null, null, 0.2f);
		landStarted = false;
		landCompleted = false;
	}

	public override void Update()
	{
		base.Update();
		if (!standPlayed && exitQueued && ChaosStopwatch.GetTimePercentage(exitStopwatchID) > 0.25f)
		{
			parent.anim.Play("Stand", -1, 0f);
			standPlayed = true;
		}
		else if (standPlayed && !crossArmPlayed && parent.anim.AnimPlayed())
		{
			parent.anim.Play("CrossArms", -1, 0f);
			crossArmPlayed = true;
		}
	}

	public override void ExecuteSkill()
	{
		if (!slamPlayed)
		{
			slamPlayed = true;
			CreateAllOrbs();
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
			return;
		}
		if (!landCompleted)
		{
			if (!landStarted)
			{
				landStarted = true;
				landStopwatch.IsRunning = true;
				parent.Partner.QueueMode("Land", spawnPosition, 1, skillID, 2);
				parent.Partner.PlayAnim("PBAoEWindup");
				parent.Partner.lightningAuraEmitter.Play(14f, parent.Partner.transform.position + Vector3.up);
				parent.SetColliderStatus(givenStatus: true, partnerStatus: true);
			}
			if (landStopwatch.IsRunning)
			{
				return;
			}
			landCompleted = true;
		}
		base.ExecuteSkill();
		for (int num = moList.Count - 1; num >= 0; num--)
		{
			if (moList[num] != null)
			{
				moList[num].ActivateNet();
			}
		}
		moList.Clear();
		if (!slamPlayed)
		{
			slamPlayed = true;
			parent.anim.Play("GroundSlam", -1, 1f);
		}
		parent.Partner.PlayAnim("PBAoELoop");
		parent.Partner.lightningAuraEmitter.Play(20f, parent.Partner.transform.position + Vector3.up);
		PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(8, parent.Partner.transform.position + Vector3.up);
	}

	public override void OnExit()
	{
		base.OnExit();
		for (int num = moList.Count - 1; num >= 0; num--)
		{
			if (moList[num] != null)
			{
				moList[num].Reset();
			}
		}
		moList.Clear();
		parent.Partner.lightningAuraEmitter.Stop();
		parent.Partner.PlayAnim("Idle");
		parent.SetColliderStatus(givenStatus: true, partnerStatus: true);
	}

	private void CreateAllOrbs()
	{
		parent.anim.Play("GroundSlam", -1, 0.5f);
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 40;
		float scale = 0.5f;
		Vector3? emitPosition = parent.transform.position;
		poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
		PoolManager.GetPoolItem<ParticleEffect>("FloorCrater").Emit(1, parent.transform.position);
		CameraController.ShakeCamera(0.25f);
		targetPosition = spawnPosition + Vector2.up;
		randomSeed = UnityEngine.Random.Range(0, orbCount);
		lfOverride.startLifetime = windupTime;
		PoolManager.GetPoolItem<ParticleEffect>("LightningField").Emit(25, spawnPosition, lfOverride);
		for (int i = 0; i < orbCount; i++)
		{
			moList.Add(CreateMetalOrb(GetCalculatedPosition(spawnPosition, i), skillID));
			moList[i].lsList.Add(targetPosition);
			moList[i].lsList.Add(GetCalculatedPosition(targetPosition, (i + 3) % orbCount));
			moList[i].lsList.Add(GetCalculatedPosition(targetPosition, (i + 1) % orbCount));
		}
	}

	private MetalOrb CreateMetalOrb(Vector2 givenPosition, string givenID, int givenCount = 5)
	{
		currentMO = Globals.ChaosInst<MetalOrb>(MetalOrb.Prefab, parent.bossObjects, givenPosition);
		currentMO.SetSkillInfo(parent.skillCategory, givenID);
		currentMO.hitCount = givenCount;
		return currentMO;
	}

	private Vector2 GetCalculatedPosition(Vector2 givenPosition, int givenIndex)
	{
		return givenPosition + 5f * Globals.GetCirclePositionVector(orbCount * 5, givenIndex * 5 + randomSeed);
	}
}

