			dashToPosCompleted = true;
			base.OnEnter();
			parent.SetColliderStatus(givenStatus: true, partnerStatus: true);
			parent.Partner.MoveAndAnimate(BlenderGirlPos, "FistPump", givenHoldAnim: true);
