private IEnumerator CreateGrid()
{
	if (gridArray != null)
	{
		yield break;
	}
	gridArray = new List<Vector2>[4];
	cornerList = new List<Vector2>();
	float gridSpread = 2.25f;
	Vector2[] tempVecArr = new Vector2[4]
	{
		Globals.GetSafeLinecastVector(stageCenter, Vector2.left, 100f, ChaosCollisions.layerAllWall),
		default,
		default,
		Globals.GetSafeLinecastVector(stageCenter, Vector2.right, 100f, ChaosCollisions.layerAllWall)
	};
	ref Vector2 reference = ref tempVecArr[1];
	reference = Vector2.Lerp(tempVecArr[0], tempVecArr[3], 0.33f);
	ref Vector2 reference2 = ref tempVecArr[2];
	reference2 = Vector2.Lerp(tempVecArr[0], tempVecArr[3], 0.67f);
	yield return null;
	for (int i = 0; i < 4; i++)
	{
		gridArray[i] = new List<Vector2>();
		gridArray[i].Add(tempVecArr[i]);
		for (int j = 0; j < 2; j++)
		{
			Vector2 incrementVec = gridSpread * ((j % 2 != 0) ? Vector2.down : Vector2.up);
			Vector2 currVec = tempVecArr[i];
			Vector2 testVec = currVec;
			while (true)
			{
				testVec = Globals.GetLinecastVector(currVec, currVec + incrementVec, ChaosCollisions.layerAllWall);
				currVec += incrementVec;
				if (!(currVec == testVec))
				{
					break;
				}
				gridArray[i].Add(currVec);
				yield return null;
			}
			if (i == 0 || i == 3)
			{
				cornerList.Add(Vector2.up + Globals.GetLinecastVector(tempVecArr[i], tempVecArr[i] + incrementVec * 99f, ChaosCollisions.layerAllWall));
			}
			yield return null;
		}
		yield return null;
	}
}

