	private ParticleSystem fgAuraEmitter;

	private ParticleSystem bgAuraEmitter;

	private ExitRoomEventHandler exitRoomEventHandler;

	private SpriteRenderer[] skullRenderers;

	private static Color disabledColor;

	public static MiniBossActivationCircle currentMiniBossActivationCircle;

	private float overheadPromptHeight = 2.5f;

	private OverheadPrompt overHeadPrompt;

	public OverheadPrompt CurrentOverheadPrompt
	{
		get
		{
