		}
		set
		{
			if (value == null && overHeadPrompt != null)
			{
				overHeadPrompt.HidePrompt(string.Empty);
				overHeadPrompt = null;
			}
		}
	}

	private void Awake()
	{
		anim = GetComponent<Animator>();
		fgAuraEmitter = base.transform.Find("AuraEmitterFG").GetComponent<ParticleSystem>();
		bgAuraEmitter = base.transform.Find("AuraEmitterBG").GetComponent<ParticleSystem>();
