		}
		LevelGenerator.levelGeneratedEventHandlers = (LevelGenerator.LevelGeneratedEventHandler)Delegate.Combine(LevelGenerator.levelGeneratedEventHandlers, new LevelGenerator.LevelGeneratedEventHandler(OnLevelGenerated));
		if (disabledColor == default(Color))
		{
			disabledColor = new Color(0f, 0f, 0f, 0.25f);
		}
	}

	private void Start()
	{
		currentMiniBossActivationCircle = this;
	}

	public void SetSkullStates(bool[] skullStates = null, bool enableAll = false, bool disableAll = false)
	{
		if (skullStates == null && !enableAll && !disableAll)
		{
			return;
		}
		for (int i = 0; i < EnemyCounterBar.maxSkulls; i++)
		{
			if (enableAll || skullStates[i])
			{
				skullRenderers[i].color = Color.black;
			}
			else if (disableAll || !skullStates[i])
			{
				skullRenderers[i].color = disabledColor;
			}
		}
	}

	private void GetExitRoomEventHandler()
	{
		Room componentInParent = GetComponentInParent<Room>();
		Transform transform = null;
		if (componentInParent != null)
		{
			transform = componentInParent.transform.Find("Enemies/ExitRoomEventHandler");
		}
		if (transform != null)
		{
			exitRoomEventHandler = transform.GetComponent<ExitRoomEventHandler>();
		}
	}

	public virtual void Update()
	{
		if (!(player == null) && !miniBossActivated)
		{
			if (player.IsDead || Vector2.Distance(player.transform.position, transform.position) > 2f)
			{
				player = null;
				CurrentOverheadPrompt = null;
				anim.Play("Disabled", -1, 0f);
			}
			else if (player.inputDevice.GetButtonDown("Interact"))
			{
				Activate();
			}
		}
	}

	private void Activate()
	{
		CurrentOverheadPrompt = null;
		miniBossActivated = true;
		CameraController.ShakeCamera();
		if (MiniBossAltar.currentMiniBossAltar != null)
		{
			MiniBossAltar.currentMiniBossAltar.Break();
		}
		if (exitRoomEventHandler == null)
		{
			GetExitRoomEventHandler();
		}
		if (exitRoomEventHandler != null)
		{
			exitRoomEventHandler.Activate();
		}
		anim.Play("Hide", -1, 0f);
		fgAuraEmitter.Emit(15);
		bgAuraEmitter.Emit(15);
	}

	private void OnLevelGenerated()
	{
		GetExitRoomEventHandler();
	}

	private void OnTriggerStay2D(Collider2D col)
	{
		if (!miniBossActivated && player == null)
		{
			player = Player.CheckForPlayer(col);
			if (player != null && !player.fsm.currentStateName.Contains("Dead"))
			{
				CurrentOverheadPrompt.Initialize(transform, player.inputDevice.inputScheme, overheadPromptHeight);
				CurrentOverheadPrompt.DisplayPrompt("Interact");
				anim.Play("Standby", -1, 0f);
			}
		}
	}

	private void OnTriggerExit2D(Collider2D col)
	{
		if (!miniBossActivated && player != null && !player.fsm.currentStateName.Contains("Dead"))
		{
			CurrentOverheadPrompt = null;
			player = null;
			anim.Play("Disabled", -1, 0f);
		}
	}

	private void OnDestroy()
	{
		LevelGenerator.levelGeneratedEventHandlers = (LevelGenerator.LevelGeneratedEventHandler)Delegate.Remove(LevelGenerator.levelGeneratedEventHandlers, new LevelGenerator.LevelGeneratedEventHandler(OnLevelGenerated));
	}
}
