public class MiniBossSummonState : Enemy.SummonState
{
	public int healthAdded;

	public int spawnCountPerWave = 1;

	private float baseCDValue;

	public new MiniBoss parent;

	public MiniBossSummonState(string newName, FSM newFSM, MiniBoss newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
		: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, 0f, newAuto)
	{
		parent = newEnt;
		disablePowerUpEffect = true;
		spawnRange = 4f;
		healthMod = new NumVarStatMod(newName, healthAdded, 10, VarStatModType.Additive, fillToNewMax: true);
		baseCDValue = newCD;
		cdResetTime = newCD * 0.5f;
		if (!parent.isFinalRoom)
		{
			StartCooldown(cdResetTime);
		}
	}

	public override bool IsReady()
	{
		if (base.IsReady())
		{
			if (minions.Count < maxMinionCount)
			{
				StartCooldown(baseCDValue);
				return true;
			}
			StartCooldown(cdResetTime);
			return false;
		}
		return false;
	}

	public override void OnEnter()
	{
		healthMod.modValue = healthAdded;
		base.OnEnter();
	}

	public override void SummonEnemies()
	{
		spawnCount = Mathf.Min(spawnCountPerWave, maxMinionCount - curMinionCount);
		for (int i = 0; i < spawnCount; i++)
		{
			SummonEnemy(Globals.GetLinecastVector(parent.myOrigin, (Vector2)parent.myOrigin + spawnRange * Globals.GetCirclePositionVector(spawnCount + 1, i + 1), ChaosCollisions.layerAllWallAndObst));
		}
		SoundManager.PlayAudioWithDistance("EnemyCast", parent.transform.position);
	}
}

