public class ShockBox : MonoBehaviour
{
	private static GameObject prefab;

	public Transform[] transArr;

	public SpriteRenderer[] spriteArr;

	public Sprite shockSprite;

	private Vector2 centerPosition = Vector2.zero;

	private Vector2[] cornerArr = new Vector2[4];

	private LightningBoss parentBoss;

	private string skillID = string.Empty;

	private float hitRange = 1f;

	private int hitCount = 1;

	private int moveStopwatchID;

	private float moveTime = 0.35f;

	private float moveLerpValue;

	private bool moveCompleted;

	private int delayStopwatchID;

	private float delayTime = 0.25f;

	private bool delayCompleted;

	private bool destroyQueued;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/ShockBox.prefab"));

	public void Initialize(LightningBoss givenBoss, string givenID, float givenRange, int givenCount, float givenMove, float givenDelay)
	{
		parentBoss = givenBoss;
		skillID = givenID;
		hitRange = givenRange;
		hitCount = givenCount;
		moveTime = givenMove;
		delayTime = givenDelay;
		centerPosition = transform.position;
		ref Vector2 reference = ref cornerArr[0];
		reference = centerPosition + new Vector2(-1f, 1f) * hitRange;
		ref Vector2 reference2 = ref cornerArr[1];
		reference2 = centerPosition + new Vector2(1f, 1f) * hitRange;
		ref Vector2 reference3 = ref cornerArr[2];
		reference3 = centerPosition + new Vector2(1f, -1f) * hitRange;
		ref Vector2 reference4 = ref cornerArr[3];
		reference4 = centerPosition + new Vector2(-1f, -1f) * hitRange;
	}

	private void Start()
	{
		moveStopwatchID = ChaosStopwatch.Begin(moveTime);
	}

	private void FixedUpdate()
	{
		if (destroyQueued)
		{
			return;
		}
		if (!moveCompleted)
		{
			moveLerpValue = Globals.GetSmoothLerpValue(ChaosStopwatch.GetTimePercentage(moveStopwatchID));
			for (int i = 0; i < 4; i++)
			{
				transArr[i].position = Vector2.Lerp(centerPosition, cornerArr[i], moveLerpValue);
			}
			if (!(moveLerpValue >= 1f))
			{
				return;
			}
			moveCompleted = true;
			delayStopwatchID = ChaosStopwatch.Begin(delayTime);
			SoundManager.PlayWithDistAndSPR("IonSpike", transform.position, 0.9f);
			for (int j = 0; j < 4; j++)
			{
				CreateWarning(cornerArr[j], cornerArr[(j + 1) % 4]);
			}
		}
		if (!delayCompleted)
		{
			if (!ChaosStopwatch.Check(delayStopwatchID))
			{
				return;
			}
			delayCompleted = true;
		}
		for (int k = 0; k < 4; k++)
		{
			CreateStream(cornerArr[k], cornerArr[(k + 1) % 4]);
			spriteArr[k].sprite = shockSprite;
			PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(3, transArr[k].position);
			PoolManager.GetPoolItem<ParticleEffect>("LightningAuraEffect").Emit(2, transArr[k].position);
		}
		CameraController.ShakeCamera(0.25f);
		destroyQueued = true;
		Object.Destroy(gameObject, (float)hitCount * 0.125f);
	}

	private void CreateStream(Vector2 givenStart, Vector2 givenEnd)
	{
		if (parentBoss != null)
		{
			parentBoss.CreateStream(skillID, givenStart, givenEnd, hitCount, 0.1f, 0.375f);
		}
	}

	private void CreateWarning(Vector2 givenStart, Vector2 givenEnd)
	{
		if (parentBoss != null)
		{
			parentBoss.CreateWarning(givenStart, givenEnd, 0.25f);
		}
	}

	private void OnDestroy()
	{
		ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("MetalDebrisEmitter");
		ParticleEffect poolItem2 = PoolManager.GetPoolItem<ParticleEffect>("MetalSparkEmitter");
		for (int i = 0; i < 4; i++)
		{
			poolItem.Emit(5, transArr[i].position, ParticleEffectOverrides.StartSpeed1);
			poolItem2.Emit(8, transArr[i].position);
		}
	}
}

using UnityEngine;

public class StunEffect : MonoBehaviour
{
	private const int maxStarCount = 5;

	private const float starUnitRatio = 0.2f;

	private Animator anim;

	private FollowTransform followTransform;

	private SpriteRenderer[] sprites = new SpriteRenderer[5];

	public float duration = 1f;

	public bool playOnStart;

	private bool playing;

	public int stopwatchID;

	public float fullStunOverride;

	public bool useDurationAsFullStun;

	private int disabledStarCount = 5;

	private int activeStarCount;

	private float timeRemaining;

	private float timePercentage;

	private float starRemoveThreshold;

	private AudioSource stunAudio;

	private void Awake()
	{
		anim = GetComponent<Animator>();
		followTransform = GetComponent<FollowTransform>();
		for (int i = 0; i < 5; i++)
		{
			sprites[i] = transform.Find("StarSprite" + i).GetComponent<SpriteRenderer>();
		}
	}

	private void Start()
	{
		if (playOnStart)
		{
			Play();
		}
		else
		{
			Stop();
		}
	}

	private void Update()
	{
		if (!playing)
		{
			return;
		}
		timeRemaining = ChaosStopwatch.GetRemainingTime(stopwatchID);
		if (timeRemaining == 0f)
		{
			Stop();
		}
		if (useDurationAsFullStun)
		{
			timePercentage = ChaosStopwatch.GetTimePercentage(stopwatchID);
		}
		else if (fullStunOverride > 0f)
		{
			if (timeRemaining > fullStunOverride)
			{
				return;
			}
			timePercentage = 1f - timeRemaining / fullStunOverride;
		}
		else
		{
			if (timeRemaining > 1.25f)
			{
				return;
			}
			timePercentage = 1f - timeRemaining / 1.25f;
		}
		starRemoveThreshold = (float)(disabledStarCount + 1) * 0.2f;
		if (activeStarCount > 0 && timePercentage >= starRemoveThreshold)
		{
			sprites[disabledStarCount].enabled = false;
			disabledStarCount++;
			activeStarCount--;
		}
	}

	public void Readjust(float timeRemaining = -1f, int givenStopwatchID = -1)
	{
		if (givenStopwatchID > -1)
		{
			stopwatchID = givenStopwatchID;
		}
		if (timeRemaining == -1f)
		{
			timeRemaining = ChaosStopwatch.GetRemainingTime(stopwatchID);
		}
		else
		{
			ChaosStopwatch.Stop(stopwatchID);
			stopwatchID = ChaosStopwatch.Begin(timeRemaining);
		}
		if (useDurationAsFullStun)
		{
			timePercentage = ChaosStopwatch.GetTimePercentage(stopwatchID);
		}
		else if (fullStunOverride > 0f)
		{
			timePercentage = 1f - Mathf.Clamp(timeRemaining / fullStunOverride, 0f, 1f);
		}
		else
		{
			timePercentage = 1f - Mathf.Clamp(timeRemaining / 1.25f, 0f, 1f);
		}
		for (int i = 0; i < 5; i++)
		{
			sprites[i].enabled = timePercentage < (float)(i + 1) * 0.2f;
		}
	}

	public void Play(int externalStopwatchID = -1, Transform parentTransform = null, Vector3 followOffset = default(Vector3))
	{
		gameObject.SetActive(value: true);
		playing = true;
		activeStarCount = 5;
		disabledStarCount = 0;
		anim.Play("SpinAll");
		for (int i = 0; i < 5; i++)
		{
			sprites[i].enabled = true;
		}
		stopwatchID = externalStopwatchID;
		if (ChaosStopwatch.Check(stopwatchID))
		{
			stopwatchID = ChaosStopwatch.Begin(duration);
		}
		if (parentTransform != null)
		{
			followTransform.followTransform = parentTransform;
			followTransform.followOffset = followOffset;
			stunAudio = SoundManager.PlayAudioWithDistance("StunEffect", parentTransform.position);
		}
	}

	public void Stop(bool playRecoveryFX = false)
	{
		playing = false;
		activeStarCount = 0;
		disabledStarCount = 5;
		fullStunOverride = 0f;
		useDurationAsFullStun = false;
		anim.Play("Idle");
		for (int i = 0; i < 5; i++)
		{
			sprites[i].enabled = false;
		}
		ChaosStopwatch.Stop(stopwatchID);
		followTransform.followTransform = null;
		followTransform.followOffset = Vector3.zero;
		if (stunAudio != null)
		{
			stunAudio.Stop();
			stunAudio = null;
		}
		if (playRecoveryFX)
		{
			SoundManager.PlayAudioWithDistance("StunRecover", transform.position);
			PoolManager.GetPoolItem<ParticleEffect>("StunRecoverEmote").Emit(1, transform.position);
		}
		gameObject.SetActive(value: false);
	}
}

