using UnityEngine;

public class FloorSpike : MonoBehaviour
{
	public enum FloorSpikeState
	{
		Disabled,
		Primed,
		Activated
	}

	public enum FloorSpikeMode
	{
		Trigger,
		Static,
		Auto
	}

	private Attack attack;

	private Animator anim;

	private SortSpriteLayer spriteSorter;

	public FloorSpikeState currentState;

	public FloorSpikeMode mode;

	public float disabledDuration;

	public float primeDuration;

	public float activeDuration;

	public float startTime;

	private int disabledStopwatchID = -1;

	private int primeStopwatchID = -1;

	private int activeStopwatchID = -1;

	public void Awake()
	{
		attack = transform.Find("AttackBox").GetComponent<Attack>();
		spriteSorter = GetComponent<SortSpriteLayer>();
		anim = GetComponent<Animator>();
	}

	private void Start()
	{
		attack.atkInfo = attack.GenerateAttackInfo(StatManager.GetSkillData(Enemy.globalEnemySkillCategory, (mode != FloorSpikeMode.Static) ? "FloorSpike" : "FloorSpikeStatic"), 1, isUltimate: false);
		switch (currentState)
		{
		case FloorSpikeState.Activated:
			Activate();
			break;
		case FloorSpikeState.Disabled:
			Disable(startTime);
			break;
		case FloorSpikeState.Primed:
			Prime();
			break;
		}
	}

	public void Update()
	{
		switch (currentState)
		{
		case FloorSpikeState.Primed:
			if (ChaosStopwatch.Check(primeStopwatchID))
			{
				Activate();
			}
			break;
		case FloorSpikeState.Activated:
			if (mode != FloorSpikeMode.Static && ChaosStopwatch.Check(activeStopwatchID))
			{
				Disable();
			}
			break;
		case FloorSpikeState.Disabled:
			if (mode == FloorSpikeMode.Auto && ChaosStopwatch.Check(disabledStopwatchID))
			{
				Prime();
			}
			break;
		}
	}

	public void OnTriggerEnter2D(Collider2D col)
	{
		if (currentState == FloorSpikeState.Disabled && mode != FloorSpikeMode.Static && mode != FloorSpikeMode.Auto && (!(col.gameObject.name != "AllyFloorContact") || !(col.gameObject.name != "EnemyFloorContact")))
		{
			Prime();
		}
	}

	public void Prime()
	{
		primeStopwatchID = ChaosStopwatch.Begin(primeDuration);
		spriteSorter.enabled = false;
		currentState = FloorSpikeState.Primed;
		anim.Play("Activating", -1, 0f);
		SoundManager.PlayAudioWithDistance("Switch", transform.position, null, 9f);
	}

	public void Activate()
	{
		spriteSorter.enabled = true;
		activeStopwatchID = ChaosStopwatch.Begin(activeDuration);
		currentState = FloorSpikeState.Activated;
		anim.Play("Activated", -1, 0f);
		SoundManager.PlayAudioWithDistance("FloorSpike", transform.position, null, 9f);
	}

	public void Disable(float additionalTime = 0f)
	{
		spriteSorter.enabled = false;
		disabledStopwatchID = ChaosStopwatch.Begin(disabledDuration + additionalTime);
		currentState = FloorSpikeState.Disabled;
		anim.Play("Idle");
	}
}
