	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Environment/Portal.prefab"));

	public void Awake()
	{
		portalLight = transform.Find("PortalLight").GetComponent<Light>();
		portalSprite = transform.Find("PortalSprite").GetComponent<SpriteRenderer>();
		shadowSprite = transform.Find("ShadowSprite").GetComponent<SpriteRenderer>();
