	public void InitColor(Color givenColor)
	{
		color = givenColor;
		portalLight.color = color;
		portalSprite.color = color;
		circlePartSys.startColor = color;
		circlePartSys.Play();
		edgePartSys.startColor = color;
		edgePartSys.Play();
	}

	public void Start()
	{
		InitColor(color);
		if (createReturnPortal)
		{
			returnPortal = Object.Instantiate(Prefab, targetLocation, Quaternion.identity).GetComponent<Portal>();
			returnPortal.color = color;
			returnPortal.targetLocation = transform.position;
			returnPortal.targetSpawnOffset = returnPortalSpawnOffset;
			returnPortal.createReturnPortal = false;
		}
		initialized = true;
		PlayPortalEffect();
	}

	private void OnTriggerEnter2D(Collider2D col)
	{
		if (col.gameObject.tag == "Player" && (col.gameObject.name == "AllyFloorContact" || col.gameObject.name == "IgnoreFloorContact"))
		{
			Player component = col.gameObject.transform.parent.GetComponent<Player>();
			if (!(component == null) && !component.IsDead)
			{
				StartCoroutine(TeleportPlayer());
			}
		}
	}

	private void PlayPortalEffect()
	{
		if (initialized)
		{
			SpawnPortal poolItem = PoolManager.GetPoolItem<SpawnPortal>();
			if (poolItem != null && transform != null)
			{
				poolItem.Spawn(transform.position, color);
			}
		}
	}

