				}
			}
			return;
		}
		for (int k = 0; k < array.Length; k++)
		{
			for (int l = 0; l < array[k].globalDecorations0.Count; l++)
			{
				if (array[k].globalDecorations0[l] is PitDecoration)
				{
					array[k].globalDecorations0[l].spawnChance = HallwayPitDecoration.defaultPitSpawnChance;
				}
