public static class RunData
{
	public delegate void RunEvent();

	public static bool runStarted = false;

	public static bool runCompleted = false;

	public static List<Tuple<string, string>> timestampList = new List<Tuple<string, string>>();

	public static Dictionary<int, PlayerRunData> prdDict = new Dictionary<int, PlayerRunData>();

	public static bool reqSkillStoreFound = false;

	public static bool reqItemStoreFound = false;

	public static bool miscCursedStoreFound = false;

	public static bool miscPinataRoomFound = false;

	public static bool miscNurseRoomFound = false;

	public static bool miscSlotsRoomFound = false;

	public static bool miscCollectorRoomFound = false;

	public static bool miscTailorRoomFound = false;

	public static bool miscBankerRoomFound = false;

	public static bool superSuraDefeated = false;

	public static RunEvent runStartEventHandlers;

	public static RunEvent runResetEventHandlers;

	public static void Reset()
	{
		runStarted = false;
		runCompleted = false;
		timestampList.Clear();
		prdDict.Clear();
		reqSkillStoreFound = false;
		reqItemStoreFound = false;
		miscCursedStoreFound = false;
		miscPinataRoomFound = false;
		miscNurseRoomFound = false;
		miscSlotsRoomFound = false;
		miscCollectorRoomFound = false;
		miscTailorRoomFound = false;
		miscBankerRoomFound = false;
		superSuraDefeated = false;
		if (runResetEventHandlers != null)
		{
			runResetEventHandlers();
		}
	}

	public static void InitRun()
	{
		if (!runStarted)
		{
			runStarted = true;
			timestampList.Clear();
			prdDict.Clear();
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				prdDict[player.playerID] = new PlayerRunData(player);
			}
			if (runStartEventHandlers != null)
			{
				runStartEventHandlers();
			}
		}
	}

	public static void EndRun()
	{
		if (runCompleted)
		{
			return;
		}
		runCompleted = true;
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (prdDict.ContainsKey(player.playerID))
			{
				prdDict[player.playerID].End(player);
			}
		}
	}

	public static void AddTimeStamp()
	{
		if (runStarted && !runCompleted && timestampList != null)
		{
			timestampList.Add(new Tuple<string, string>(GameController.CurrentSceneName, Globals.TimeToString(GameController.totalTime)));
		}
	}

	public static int GetPvpWinnerID()
	{
		foreach (PlayerRunData value in prdDict.Values)
		{
			if (value != null && value.pvpWon)
			{
				return value.playerID;
			}
		}
		return -1;
	}

	public static void SetPvpWinner(int givenID)
	{
		foreach (PlayerRunData value in prdDict.Values)
		{
			if (value != null)
			{
				value.pvpWon = value.playerID == givenID;
			}
		}
	}

	public static void GiveWinToken(int givenID)
	{
		if (prdDict.ContainsKey(givenID))
		{
			prdDict[givenID].winTokenCount++;
		}
	}

	public static PlayerRunData GetWinnerData()
	{
		PlayerRunData playerRunData = null;
		foreach (PlayerRunData value in prdDict.Values)
		{
			if (value != null)
			{
				if (playerRunData == null)
				{
					playerRunData = value;
				}
				else if (value.winTokenCount > playerRunData.winTokenCount)
				{
					playerRunData = value;
				}
				else if (value.winTokenCount == playerRunData.winTokenCount && Globals.RandBool)
				{
					playerRunData = value;
				}
			}
		}
		return playerRunData;
	}

	public static PlayerRunData GetOtherData(int givenID)
	{
		foreach (PlayerRunData value in prdDict.Values)
		{
			if (value != null && value.playerID != givenID)
			{
				return value;
			}
		}
		return null;
	}

	public static void PrintRunData()
	{
		string empty = string.Empty;
		empty += "\n";
		empty += "Win Tokens:\n";
		string text;
		foreach (PlayerRunData value in prdDict.Values)
		{
			text = empty;
			empty = text + value.playerID + " : " + value.winTokenCount + "\n";
		}
		empty += "\n";
		text = empty;
		empty = text + "Cursed Store: " + miscCursedStoreFound + "\n";
		text = empty;
		empty = text + "Pinata Room: " + miscPinataRoomFound + "\n";
		text = empty;
		empty = text + "Nurse Room: " + miscNurseRoomFound + "\n";
		text = empty;
		empty = text + "Slots Room: " + miscSlotsRoomFound + "\n";
		text = empty;
		empty = text + "Collector Room: " + miscCollectorRoomFound + "\n";
		text = empty;
		empty = text + "Tailor Room: " + miscTailorRoomFound + "\n";
		text = empty;
		empty = text + "Banker Room: " + miscBankerRoomFound + "\n";
		text = empty;
		empty = text + "Super Sura: " + superSuraDefeated + "\n";
		Debug.Log(empty);
	}
}
