	public static readonly string prefabPath = "Assets/Prefabs/Environment/SpawnPortal.prefab";

	private static GameObject prefab;

	public static Color enemyColor = new Color(1f, 0f, 0f, 1f);

	public static Color allyColor = new Color(0f, 1f, 1f, 1f);

	private Animator anim;

	private SpriteRenderer portalSprite;

	private Light portalLight;

	private ParticleSystem partEmitter;

	private ParticleSystem waveEmitter;

	private ParticleSystem closeEmitter;

	public Color portalColor;

	private Color tempColor;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get(prefabPath));

	private void Awake()
	{
		anim = GetComponent<Animator>();
		portalSprite = base.transform.Find("SpawnPortalSprite").GetComponent<SpriteRenderer>();
		portalLight = base.transform.Find("SpawnPortalLight").GetComponent<Light>();
		Transform transform = base.transform.Find("PortalParticles");
		partEmitter = transform.Find("ParticleEmitter").GetComponent<ParticleSystem>();
		waveEmitter = transform.Find("WaveEmitter").GetComponent<ParticleSystem>();
		closeEmitter = transform.Find("CloseEmitter").GetComponent<ParticleSystem>();
	}

	private void Start()
	{
		Reset();
	}

	private void Update()
	{
		if (anim.AnimPlayed())
		{
			Reset();
		}
	}

	private Color GetSpriteColor(Color color)
	{
		tempColor = color;
		tempColor.a = 0.9f;
		return tempColor;
	}

	public void Spawn(Vector3 location, Color? color = null, float scale = 1f, bool shakeCamera = true)
	{
		transform.position = location;
		transform.localScale = Vector3.one * scale;
		portalColor = ((!color.HasValue) ? Color.white : color.Value);
		portalSprite.color = GetSpriteColor(portalColor);
		portalLight.color = portalColor;
		partEmitter.startColor = portalColor;
		waveEmitter.startColor = portalColor;
		closeEmitter.startColor = portalColor;
		gameObject.SetActive(value: true);
		anim.Play("SpawnPortal", -1, 0f);
		SoundManager.PlayAudioWithDistance("Teleport", transform.position);
		if (shakeCamera)
		{
			CameraController.ShakeCamera(0.1f);
		}
	}

	public void Reset()
	{
		anim.Play("SpawnPortal", -1, 1f);
		gameObject.SetActive(value: false);
	}
}
