[Serializable]
public class GameVars
{
	private Dictionary<GameVarsKey, bool> boolDict;

	private Dictionary<GameVarsKey, int> intDict;

	private Dictionary<GameVarsKey, string> strDict;

	private RunHistoryEntry[] runEntries;

	private LoadoutEntry[] p1Loadouts;

	private LoadoutEntry[] p2Loadouts;

	public GameVars()
	{
		Reset();
	}

	public void Reset()
	{
		boolDict = new Dictionary<GameVarsKey, bool>();
		intDict = new Dictionary<GameVarsKey, int>();
		strDict = new Dictionary<GameVarsKey, string>();
		boolDict[GameVarsKey.NewUpdate] = false;
		intDict[GameVarsKey.TitleBG] = 0;
		intDict[GameVarsKey.BgmTrack] = 0;
		runEntries = new RunHistoryEntry[3];
		p1Loadouts = new LoadoutEntry[6];
		p2Loadouts = new LoadoutEntry[6];
	}

	public bool GetBoolValue(GameVarsKey givenKey)
	{
		if (boolDict.ContainsKey(givenKey))
		{
			return boolDict[givenKey];
		}
		boolDict[givenKey] = false;
		return false;
	}

	public int GetIntValue(GameVarsKey givenKey)
	{
		if (intDict.ContainsKey(givenKey))
		{
			return intDict[givenKey];
		}
		intDict[givenKey] = 0;
		return 0;
	}

	public string GetStrValue(GameVarsKey givenKey)
	{
		if (strDict.ContainsKey(givenKey))
		{
			return strDict[givenKey];
		}
		strDict[givenKey] = string.Empty;
		return string.Empty;
	}

	public RunHistoryEntry[] GetRunEntries()
	{
		if (runEntries == null)
		{
			runEntries = new RunHistoryEntry[3];
		}
		return (RunHistoryEntry[])runEntries.Clone();
	}

	public LoadoutEntry[] GetLoadouts(int playerID = 0)
	{
		if (p1Loadouts == null)
		{
			p1Loadouts = new LoadoutEntry[6];
		}
		if (p2Loadouts == null)
		{
			p2Loadouts = new LoadoutEntry[6];
		}
		if (p1Loadouts.Length < 6)
		{
			Array.Resize(ref p1Loadouts, 6);
		}
		if (p2Loadouts.Length < 6)
		{
			Array.Resize(ref p2Loadouts, 6);
		}
		if (playerID == 0)
		{
			return p1Loadouts;
		}
		return p2Loadouts;
	}

	public void SetValue(GameVarsKey givenKey, bool givenValue)
	{
		boolDict[givenKey] = givenValue;
	}

	public void SetValue(GameVarsKey givenKey, int givenValue)
	{
		intDict[givenKey] = givenValue;
	}

	public void SetValue(GameVarsKey givenKey, string givenValue)
	{
		strDict[givenKey] = givenValue;
	}

	public void SetRunEntry(RunHistoryEntry runHistoryEntry)
	{
		runEntries[(int)runHistoryEntry.gameMode] = runHistoryEntry;
	}

	public void ClearRunEntries()
	{
		for (int i = 0; i < runEntries.Length; i++)
		{
			runEntries[i] = null;
		}
	}

	public void SetLoadoutEntry(LoadoutEntry newLoadout, int loadoutIndex = 0, int playerID = 0)
	{
		if (playerID == 0)
		{
			p1Loadouts[loadoutIndex] = newLoadout;
		}
		else
		{
			p2Loadouts[loadoutIndex] = newLoadout;
		}
	}
}
