[Serializable]
public class LoadoutEntry
{
	public string outfitID = "Hope";

	public string relicID = "PlayerStart";

	public string[] arcanaIDs = new string[4] { "WindSlashBasic", "Dash", "ShootFireArc", "ShootFireball" };

	private static readonly string[] defaultArcanaIDs = new string[4] { "WindSlashBasic", "Dash", "ShootFireArc", "ShootFireball" };

	public void Sanitize(Player curPlayer = null)
	{
		if (!Item.IsUnlocked(relicID))
		{
			relicID = "PlayerStart";
		}
		if (!(curPlayer != null))
		{
			return;
		}
		for (int i = 0; i < arcanaIDs.Length; i++)
		{
			if (!curPlayer.skillsDict.ContainsKey(arcanaIDs[i]) || !curPlayer.skillsDict[arcanaIDs[i]].isUnlocked)
			{
				arcanaIDs[i] = defaultArcanaIDs[i];
			}
		}
		if (!Outfit.OutfitExists(outfitID) || !Outfit.OutfitIsAvailable(outfitID))
		{
			outfitID = "Hope";
		}
	}

	public void Reset()
	{
		outfitID = "Hope";
		relicID = "PlayerStart";
		arcanaIDs[0] = "WindSlashBasic";
		arcanaIDs[1] = "Dash";
		arcanaIDs[2] = "ShootFireArc";
		arcanaIDs[3] = "ShootFireball";
	}

	public override string ToString()
	{
		return "Outfit: " + outfitID + "\nRelic: " + relicID + "\nArcana0: " + arcanaIDs[0] + "\nArcana1: " + arcanaIDs[1] + "\nArcana2: " + arcanaIDs[2] + "\nArcana3: " + arcanaIDs[3];
	}
}
