	private void Awake()
	{
		if (instance != null && instance != this)
		{
			Object.Destroy(gameObject);
			return;
		}
		instance = this;
		Object.DontDestroyOnLoad(gameObject);
		for (int i = 0; i < entries.Length; i++)
		{
			entries[i] = new RunHistoryEntryUI();
			entries[i].LoadRefs(transform.Find("HistoryLog/LogEntry" + i));
		}
		graphicComps = GetComponentsInChildren<Graphic>();
		resetText = transform.Find("HistoryLog/ResetPrompt/ResetText").GetComponent<Text>();
		resetImage = transform.Find("HistoryLog/ResetPrompt/ResetImage").GetComponent<Image>();
		TextManager.AddUIRef("runHistoryUI-resetData", resetText);
	}

	private void Start()
	{
		LoadData();
		Toggle(show: false);
	}

	private void Update()
	{
		if (isActive && !GameUI.pauseMenu.paused)
		{
			if (currentPlayer == null || Vector2.Distance(currentPlayer.transform.position, activationPosition) > 4f)
			{
				Toggle(show: false);
			}
			else if (confirmationRequested)
			{
				HandleConfirm();
			}
			else if (inputDev != null && !(currentPlayer == null) && inputDev.GetButtonDown("Interact"))
			{
				currentPlayer.fsm.ChangeState("Paused");
				ConfirmHandlerUI.RequestConfirmation(confirmCount);
				confirmationRequested = true;
				confirmationStatus = false;
			}
		}
	}

	private void HandleConfirm()
	{
		if (!confirmationRequested)
		{
			return;
		}
		if (ConfirmHandlerUI.RequestInProgress)
		{
			confirmationStatus = ConfirmHandlerUI.RequestConfirmation();
			return;
		}
		confirmationRequested = false;
		if (confirmationStatus)
		{
			confirmCount++;
			if (confirmCount < resetConfirmReq)
			{
				ConfirmHandlerUI.RequestConfirmation(confirmCount);
				confirmationRequested = true;
				confirmationStatus = false;
				return;
			}
			ResetRunHistory();
			SoundManager.PlayAudio("Equip");
		}
		confirmCount = 0;
		confirmationRequested = false;
		confirmationStatus = false;
		currentPlayer.fsm.ChangeState(currentPlayer.fsm.defaultStateName);
	}

	private void ResetRunHistory()
	{
		GameDataManager.gameVars.ClearRunEntries();
		GameDataManager.SaveGameVars();
		LoadData();
		if (shelfRef != null)
		{
			shelfRef.UpdateTrophies();
		}
		Load();
	}

	public static void LoadData()
	{
		runEntryData = GameDataManager.gameVars.GetRunEntries();
	}

	private void Load()
	{
		ResetEntries();
		for (int i = 0; i < runEntryData.Length; i++)
		{
			if (runEntryData[i] != null)
			{
				switch (runEntryData[i].gameMode)
				{
				case GameMode.Standard:
					entries[0].Load(runEntryData[i], this);
					entries[0].newRecordMarker.enabled = newRecordFlags[0];
					break;
				case GameMode.Speed:
					entries[1].Load(runEntryData[i], this);
					entries[1].newRecordMarker.enabled = newRecordFlags[1];
					break;
				case GameMode.Endless:
					entries[2].Load(runEntryData[i], this);
					entries[2].newRecordMarker.enabled = newRecordFlags[2];
					break;
				}
			}
		}
	}

	public void Toggle(bool show = true, Player givenPlayer = null, TrophyShelf givenShelf = null)
	{
		if (show)
		{
			Load();
			if (givenPlayer == null && GameController.activePlayers.Length > 0)
			{
				givenPlayer = GameController.activePlayers[0];
			}
			if (givenPlayer != null)
			{
				currentPlayer = givenPlayer;
				activationPosition = givenPlayer.transform.position;
				inputDev = givenPlayer.inputDevice;
				resetImage.sprite = GameUI.GetInputSprite(inputDev.inputScheme, "Interact");
			}
			if (givenShelf != null)
			{
				shelfRef = givenShelf;
			}
			isActive = true;
			if (gameObject != null)
			{
				gameObject.SetActive(value: true);
			}
			Graphic[] array = graphicComps;
			foreach (Graphic graphic in array)
			{
				graphic.CrossFadeAlpha(1f, 0.18f, ignoreTimeScale: false);
			}
		}
		else
		{
			currentPlayer = null;
			activationPosition = Vector2.zero;
			inputDev = null;
			isActive = false;
			if (gameObject != null)
			{
				gameObject.SetActive(value: false);
			}
			Graphic[] array2 = graphicComps;
			foreach (Graphic graphic2 in array2)
			{
				graphic2.CrossFadeAlpha(0f, 0f, ignoreTimeScale: false);
			}
			ConfirmHandlerUI.ForceQuitConfirmation();
		}
	}

	private void ResetEntries()
	{
		for (int i = 0; i < entries.Length; i++)
		{
			if (entries[i] != null)
			{
				entries[i].Reset();
			}
		}
	}
}

