				loadoutEntries[i] = new LoadoutEntry();
			}
			loadoutEntries[i].outfitID = tempLoadoutEntries[i].outfitID;
			loadoutEntries[i].relicID = tempLoadoutEntries[i].relicID;
			loadoutEntries[i].arcanaIDs[0] = tempLoadoutEntries[i].arcanaIDs[0];
			loadoutEntries[i].arcanaIDs[1] = tempLoadoutEntries[i].arcanaIDs[1];
			loadoutEntries[i].arcanaIDs[2] = tempLoadoutEntries[i].arcanaIDs[2];
			loadoutEntries[i].arcanaIDs[3] = tempLoadoutEntries[i].arcanaIDs[3];
			loadoutEntries[i].Sanitize(curPlayer);
