		{
			curPlayer.EquipOutfit(curLoadout.outfitID);
			GameDataManager.Save(updateCurrentData: true, updatePlayerData: true);
			curPlayer.inventory.ClearInventory(keepHubOnly: false, keepCursed: true);
			if (!GameController.pvpOn && !SceneManager.GetActiveScene().name.Contains("PvP"))
			{
				curPlayer.GiveDesignatedItem(curLoadout.relicID);
			}
			basicSlot = curPlayer.GetBasicSkill().skillSlot;
			dashSlot = curPlayer.GetDashSkill().skillSlot;
			stdSlot = curPlayer.GetAnyStandardSkill().skillSlot;
			tempSkill = curPlayer.GetSignatureSkill();
			sigSlot = tempSkill.skillSlot;
			tempSkill.isSignature = false;
			tempSkill.SetEmpowered(givenStatus: false, EmpowerStatMods.DefaultEmpowerMod);
			for (int i = 0; i < 6; i++)
			{
				curPlayer.AssignSkillSlot(i, string.Empty);
			}
			curPlayer.AssignSkillSlot(basicSlot, curLoadout.arcanaIDs[0]);
			curPlayer.AssignSkillSlot(dashSlot, curLoadout.arcanaIDs[1]);
			curPlayer.AssignSkillSlot(stdSlot, curLoadout.arcanaIDs[2]);
			curPlayer.AssignSkillSlot(sigSlot, curLoadout.arcanaIDs[3], setSignature: true, signatureStatus: true);
			curPlayer.lowerHUD.cooldownUI.RefreshEntries();
			curGlassFlash.enabled = false;
			curGlassFlash.enabled = true;
			curGlassFlash.color = Color.white;
			curGlassFlash.CrossFadeAlpha(0f, 0.25f, ignoreTimeScale: true);
			if (curPlayer.health.HealthPercentage != 1f)
			{
				curPlayer.health.RestoreHealth(999, showDisplayText: false, playSound: false, fullyRestoreHealth: true);
			}
		}
	}

	private void SaveCurrent()
	{
		SoundManager.PlayAudio("CameraShutter");
		loadoutEntries[curNavIndex].outfitID = curPlayer.outfitID;
		loadoutEntries[curNavIndex].relicID = curPlayer.designatedItemID;
		loadoutEntries[curNavIndex].arcanaIDs[0] = curPlayer.GetBasicSkill().skillID;
		loadoutEntries[curNavIndex].arcanaIDs[1] = curPlayer.GetDashSkill().skillID;
		loadoutEntries[curNavIndex].arcanaIDs[2] = curPlayer.GetAnyStandardSkill().skillID;
		loadoutEntries[curNavIndex].arcanaIDs[3] = curPlayer.GetSignatureSkill().skillID;
		GameDataManager.gameVars.SetLoadoutEntry(loadoutEntries[curNavIndex], curNavIndex, curPlayer.playerID);
		UpdateEntry(curNavIndex);
		loadoutDimmers[curNavIndex].enabled = true;
		loadoutDimmers[curNavIndex].color = Color.white;
		loadoutDimmers[curNavIndex].CrossFadeAlpha(0f, 0.25f, ignoreTimeScale: true);
		isDirty = true;
	}

	private void HandleNavigation()
	{
		curInputDir = Globals.GetInputDirection(inputDev.GetMoveVector());
		if (curInputDir == InputDirection.None)
		{
			initNavDelayReset = true;
			navTimer.IsRunning = false;
			autoNavTimer.IsRunning = false;
		}
		else
		{
			if (navTimer.IsRunning || autoNavTimer.IsRunning)
			{
				return;
			}
			if (curInputDir == InputDirection.Up)
			{
				curNavIndex--;
			}
			else
			{
				if (curInputDir != InputDirection.Down)
				{
					return;
				}
				curNavIndex++;
			}
			if (curNavIndex < 0)
			{
				curNavIndex = 5;
			}
			else if (curNavIndex > 5)
			{
				curNavIndex = 0;
			}
			SoundManager.PlayAudio("MenuMove");
			if (initNavDelayReset)
			{
				initNavDelayReset = false;
				navTimer.IsRunning = true;
			}
			else
			{
				autoNavTimer.IsRunning = true;
			}
			HighlightLoadout(curNavIndex);
		}
	}

	private void HighlightLoadout(int givenIndex = 0)
	{
		for (int i = 0; i < 6; i++)
		{
			if (givenIndex == i)
			{
				loadoutSelMarkers[i].enabled = true;
				loadoutDimmers[i].color = dimmerColor;
				loadoutDimmers[i].enabled = false;
			}
			else
			{
				loadoutSelMarkers[i].enabled = false;
				loadoutDimmers[i].color = dimmerColor;
				loadoutDimmers[i].enabled = true;
			}
		}
	}

	private void RandomizeCamPose()
	{
		curOutfitImage.sprite = wizardPoses.GetRandomValue();
		curOutfitImage.SetNativeSize();
	}

	public void Activate(Player givenPlayer, Vector2 givenPos)
	{
		if (!(givenPlayer == null))
		{
			curNavIndex = 0;
			RandomizeCamPose();
			HighlightLoadout(curNavIndex);
			ToggleConfirmWindow(show: false);
			gameObject.SetActive(value: true);
			curPlayer = givenPlayer;
			inputDev = givenPlayer.inputDevice;
			startRelicID = curPlayer.designatedItemID;
			curGlassFlash.color = Globals.transparentColor;
			LoadData();
			UpdateAllEntries();
			UpdateCurrentLoadout();
			cancelImage.sprite = GameUI.GetInputSprite(inputDev.inputScheme, "Cancel");
			saveImage.sprite = GameUI.GetInputSprite(inputDev.inputScheme, "Interact");
			equipImage.sprite = GameUI.GetInputSprite(inputDev.inputScheme);
			isDirty = false;
			isActive = true;
			GameUI.ToggleLowerHud(givenStatus: false, curPlayer.playerID);
			activationPosition = givenPos;
		}
	}

	private void Deactivate()
	{
		if (curPlayer != null)
		{
			GameUI.ToggleLowerHud(givenStatus: true, curPlayer.playerID);
			curPlayer.fsm.ChangeState(curPlayer.fsm.defaultStateName);
			if (curPlayer.designatedItemID != startRelicID)
			{
				curPlayer.newItemNoticeUI.Display(TextManager.GetItemName(curPlayer.designatedItemID), IconManager.GetItemIcon(curPlayer.designatedItemID));
				SoundManager.PlayAudio("Powerup");
			}
		}
		ToggleConfirmWindow(show: false);
		startRelicID = null;
		curPlayer = null;
		inputDev = null;
		isActive = false;
		gameObject.SetActive(value: false);
		curNavIndex = 0;
		if (isDirty)
		{
			GameDataManager.SaveGameVars();
		}
		isDirty = false;
	}

	public void Mirror()
	{
		cardRectTrans.anchorMin = new Vector2(1f, 0.5f);
		cardRectTrans.anchorMax = new Vector2(1f, 0.5f);
		cardRectTrans.anchoredPosition = new Vector2((0f - cardRectTrans.rect.width) / 2f, cardRectTrans.anchoredPosition.y);
		for (int i = 0; i < loadoutSelMarkers.Length; i++)
		{
			loadoutSelMarkers[i].transform.localScale = Globals.ScaleVecFlipX;
		}
		tempAnchorPosition = cameraRectTrans.anchoredPosition;
		cameraRectTrans.anchorMin = new Vector2(1f, 0.5f);
		cameraRectTrans.anchorMax = new Vector2(1f, 0.5f);
		cameraRectTrans.anchoredPosition = new Vector2((0f - cameraRectTrans.rect.width) / 2f, cameraRectTrans.anchoredPosition.y);
		cameraRectTrans.anchoredPosition = new Vector2(0f - tempAnchorPosition.x, tempAnchorPosition.y);
		tempAnchorPosition = confirmRectTrans.anchoredPosition;
		confirmRectTrans.anchorMin = new Vector2(1f, 0.5f);
		confirmRectTrans.anchorMax = new Vector2(1f, 0.5f);
		confirmRectTrans.anchoredPosition = new Vector2((0f - confirmRectTrans.rect.width) / 2f, confirmRectTrans.anchoredPosition.y);
		confirmRectTrans.anchoredPosition = new Vector2(0f - tempAnchorPosition.x, tempAnchorPosition.y);
	}
}

