6.0.2
"""Общее для records/: загрузка, схема, склейка файлов одной системы, поиск TODO.

  python recio.py FILE_OR_DIR [...]      # валидация (схема + семантика), код 1 при ошибках
  python recio.py DIR --strict           # TODO в rules/catalog/goal тоже ошибка
"""
from __future__ import annotations
import argparse, re, sys
from pathlib import Path

import yaml

Loader = getattr(yaml, "CSafeLoader", yaml.SafeLoader)

HERE = Path(__file__).parent
SCHEMA_PATH = HERE / "schema.yaml"
TODO_RE = re.compile(r"^\s*TODO\b|\bTODO:", re.I)


def load_schema() -> dict:
    return yaml.safe_load(SCHEMA_PATH.read_text(encoding="utf-8"))


def is_todo(s) -> bool:
    return isinstance(s, str) and (not s.strip() or bool(TODO_RE.search(s)))


def find_files(paths) -> list[Path]:
    out: list[Path] = []
    for p in paths:
        p = Path(p)
        if p.is_dir():
            out += sorted(x for x in p.glob("*.y*ml") if x.suffix in (".yaml", ".yml"))
        elif p.exists():
            out.append(p)
        else:
            raise FileNotFoundError(p)
    return out


def load_file(p: Path) -> dict:
    d = yaml.load(p.read_text(encoding="utf-8"), Loader=Loader) or {}
    d["_path"] = str(p)
    return d


def validate_schema(d: dict) -> list[str]:
    try:
        import jsonschema
    except ImportError:
        return _mini_validate(d)
    v = jsonschema.Draft202012Validator(load_schema())
    errs = []
    for e in sorted(v.iter_errors({k: x for k, x in d.items() if k != "_path"}), key=lambda e: list(e.path)):
        loc = "/".join(str(x) for x in e.path) or "(root)"
        errs.append(f"{loc}: {e.message[:200]}")
    return errs


def _mini_validate(d: dict) -> list[str]:  # без jsonschema: только обязательное
    errs = []

}

public void ResetNPCData()
{
	npcDataDictionary = new Dictionary<string, bool>();
	npcDataDictionary["Ward"] = true;
}

public void PushOutfitData()
{
	foreach (KeyValuePair<string, Outfit> item in Outfit.OutfitDict)
	{
		outfitDataDictionary[item.Key] = item.Value != null && item.Value.unlocked;
	}
}

public void PullOutfitData()
{
	foreach (KeyValuePair<string, bool> item in outfitDataDictionary)
	{
		if (Outfit.OutfitDict.ContainsKey(item.Key))
		{
			Outfit.OutfitDict[item.Key].unlocked = item.Value;
		}
		else if (item.Key == Outfit.normalID && item.Value)
		{
			Outfit.SetNormal();
		}
	}
}

public void ResetOutfitData()
